export const getPath = (request: Request): string => {
  const url = request.url
  const start = url.indexOf('/', url.indexOf(':') + 4)
  let i = start
  for (; i < url.length; i++) {
    const charCode = url.charCodeAt(i)
    if (charCode === 37) { // '%' - path contains percent encoding
      const qi = url.indexOf('?', i), hi = url.indexOf('#', i)
      const end = qi === -1 ? (hi === -1 ? undefined : hi)
        : (hi === -1 ? qi : Math.min(qi, hi))
      return tryDecode(url.slice(start, end), decodeURIWithPreservedPercent)
    } else if (charCode === 63 || charCode === 35) { break }
  }
  return url.slice(start, i)
}

export const getPattern = (label: string, next?: string): Pattern | null => {
  if (label === '*') { return '*' }
  const match = label.match(/^\:([^\{\}]+)(?:\{(.+)\})?$/)
  if (match) {
    const k = `${label}#${next}`
    if (!patternCache[k]) {
      patternCache[k] = match[2]
        ? (next && next[0] !== ':' && next[0] !== '*'
            ? [k, match[1], new RegExp(`^${match[2]}(?=/${next})`)]
            : [label, match[1], new RegExp(`^${match[2]}$`)])
        : [label, match[1], true]
    }
    return patternCache[k]
  }; return null
}

export const parseBody: ParseBody = async (
  request: HonoRequest | Request,
  options = Object.create(null)
) => {
  const { all = false, dot = false } = options
  const headers = isRawRequest(request) ? request.headers : request.raw.headers
  const contentType = headers.get('Content-Type')
  const mediaType = contentType?.split(';')[0].trim().toLowerCase()
  if (mediaType === 'multipart/form-data' || mediaType === 'application/x-www-form-urlencoded') {
    return parseFormData(request, { all, dot })
  }
  return {}
}

export const timingSafeEqual: TimingSafeEqual = async (
  a, b, hashFunction?: Function
): Promise<boolean> => {
  if (typeof a === 'string' && typeof b === 'string') {
    return timingSafeEqualString(a, b, hashFunction as StringHashFunction)
  }
  if (!hashFunction) { hashFunction = sha256 }
  const [sa, sb] = await Promise.all([hashFunction(a), hashFunction(b)])
  if (!sa || !sb || typeof sa !== 'string' || typeof sb !== 'string') { return false }
  return timingSafeEqualString(sa, sb)
}

export const createHash = async (data: Data, algorithm: Algorithm) => {
  let sourceBuffer: ArrayBufferView | ArrayBuffer
  if (ArrayBuffer.isView(data) || data instanceof ArrayBuffer) {
    sourceBuffer = data
  } else {
    if (typeof data === 'object') { data = JSON.stringify(data) }
    sourceBuffer = new TextEncoder().encode(String(data))
  }
  if (crypto && crypto.subtle) {
    const buf = await crypto.subtle.digest({ name: algorithm.name }, sourceBuffer as ArrayBuffer)
    return Array.prototype.map.call(
      new Uint8Array(buf), (x) => ('00' + x.toString(16)).slice(-2)).join('')
  }
  return null
}

export const sign = async (
  payload: JWTPayload, privateKey: SignatureKey,
  alg: SignatureAlgorithm = 'HS256'
): Promise<string> => {
  const encodedPayload = encodeJwtPart(payload)
  let encodedHeader
  if (typeof privateKey === 'object' && 'alg' in privateKey) {
    alg = privateKey.alg as SignatureAlgorithm
    encodedHeader = encodeJwtPart({ alg, typ: 'JWT', kid: privateKey.kid })
  } else { encodedHeader = encodeJwtPart({ alg, typ: 'JWT' }) }
  const partialToken = `${encodedHeader}.${encodedPayload}`
  const sig = await signing(privateKey, alg, utf8Encoder.encode(partialToken))
  return `${partialToken}.${encodeSignaturePart(sig)}`
}

export const verify = async (
  token: string, publicKey: SignatureKey,
  algOrOptions: SignatureAlgorithm | VerifyOptionsWithAlg
): Promise<JWTPayload> => {
  const { alg, exp = true, nbf = true, iat = true, aud, iss, typ } =
    typeof algOrOptions === 'string' ? { alg: algOrOptions } : algOrOptions
  const { header, payload } = decode(token)
  if (!isTokenHeader(header, typ)) { throw new JwtHeaderInvalid(header) }
  if (header.alg !== alg) { throw new JwtAlgorithmMismatch(alg, header.alg) }
  // time-based claim checks (exp, nbf, iat) then iss and aud ...
  const headerPayload = token.substring(0, token.lastIndexOf('.'))
  const ok = await verifying(publicKey, alg, sig, utf8Encoder.encode(headerPayload))
  if (!ok) { throw new JwtTokenSignatureMismatched(token) }
  return payload
}

export const parse = (cookie: string, name?: string): Cookie => {
  if (name && cookie.indexOf(name) === -1) { return {} }
  const result: Cookie = Object.create(null)
  for (const pairStr of cookie.split(';')) {
    const eq = pairStr.indexOf('=')
    if (eq === -1) { continue }
    const cName = trimCookieWhitespace(pairStr.substring(0, eq))
    if ((name && name !== cName) || !relaxedCookieNameRegEx.test(cName)
        || cName in result) { continue }
    let cValue = trimCookieWhitespace(pairStr.substring(eq + 1))
    if (cValue.length >= 2 && cValue[0] === '"' && cValue.endsWith('"')) cValue = cValue.slice(1, -1)
    if (validCookieValueRegEx.test(cValue)) { result[cName] = tryDecodeURIComponent(cValue); if (name) break }
  }
  return result
}

export const parseAccept = (acceptHeader: string): Accept[] => {
  if (!acceptHeader) { return [] }
  const values: Accept[] = []
  let i = 0, accept: Accept | undefined, requiresSort = false, last: Accept | undefined
  while (i < acceptHeader.length) {
    ;[i, accept] = getNextAcceptValue(acceptHeader, i)
    if (accept) {
      accept.q = parseQuality(accept.params.q ?? accept.params.Q)
      values.push(accept)
      if (last && last.q < accept.q) { requiresSort = true }; last = accept
    }
  }
  if (requiresSort) { values.sort((a, b) => b.q - a.q) }
  return values
}

export const escapeToBuffer = (str: string, buffer: StringBuffer): void => {
  const match = str.search(/[&<>'"]/) // escapeRe
  if (match === -1) { buffer[0] += str; return }
  let escape, index, lastIndex = 0
  for (index = match; index < str.length; index++) {
    switch (str.charCodeAt(index)) {
      case 34: escape = '&quot;'; break
      case 39: escape = '&#39;'; break
      case 38: escape = '&amp;'; break
      case 60: escape = '&lt;'; break
      case 62: escape = '&gt;'; break
      default: continue
    }
    buffer[0] += str.substring(lastIndex, index) + escape; lastIndex = index + 1
  }; buffer[0] += str.substring(lastIndex, index) }

export const splitPath = (path: string): string[] => {
  const paths = path.split('/')
  if (paths[0] === '') {
    paths.shift()
  }
  return paths
}

export const expandIPv6 = (ipV6: string): string => {
  const sections = ipV6.split(':')
  const last = sections.at(-1) as string
  if (IPV4_REGEX.test(last)) {
    const octets = last.split('.').map(Number)
    sections.splice(-1, 1,
      ((octets[0] << 8) | octets[1]).toString(16),
      ((octets[2] << 8) | octets[3]).toString(16))
  }
  for (let i = 0; i < sections.length; i++) {
    if (sections[i] !== '') { sections[i] = sections[i].padStart(4, '0') }
  }
  return sections.join(':')
}

export const encodeBase64 = (buf: ArrayBufferLike): string => {
  let binary = ''
  const bytes = new Uint8Array(buf)
  for (let i = 0, len = bytes.length; i < len; i++) {
    binary += String.fromCharCode(bytes[i])
  }
  return btoa(binary)
}

export const decodeBase64 = (str: string): Uint8Array<ArrayBuffer> => {
  const binary = atob(str)
  const bytes = new Uint8Array<ArrayBuffer>(new ArrayBuffer(binary.length))
  const half = binary.length / 2
  for (let i = 0, j = binary.length - 1; i <= half; i++, j--) {
    bytes[i] = binary.charCodeAt(i)
    bytes[j] = binary.charCodeAt(j)
  }
  return bytes
}

export const equal = (a: ArrayBuffer, b: ArrayBuffer): boolean => {
  if (a === b) { return true }
  if (a.byteLength !== b.byteLength) { return false }
  const va = new DataView(a)
  const vb = new DataView(b)
  let i = va.byteLength
  while (i--) {
    if (va.getUint8(i) !== vb.getUint8(i)) { return false }
  }
  return true
}
